const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Session validation
function validateSession(req) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 32) return null;
  return token;
}

// Product search endpoint with filtering
app.get('/api/v2/products/search', async (req, res) => {
  const session = validateSession(req);
  if (!session) return res.status(401).json({ error: 'unauthorized' });

  const { category, minPrice, maxPrice, sortBy, order } = req.query;

  // Build base query
  let query = 'SELECT id, name, price, category, stock_count FROM products WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (category) {
    params.push(category);
    query += ` AND category = $${paramIdx++}`;
  }

  if (minPrice) {
    params.push(parseFloat(minPrice));
    query += ` AND price >= $${paramIdx++}`;
  }

  if (maxPrice) {
    params.push(parseFloat(maxPrice));
    query += ` AND price <= $${paramIdx++}`;
  }

  // Sort handling - validated against allowlist... partially
  const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
  const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';

  // Order direction - THIS is where the injection lives
  // Developer assumed order is just ASC/DESC but doesn't validate
  const orderDir = order || 'ASC';
  query += ` ORDER BY ${sortColumn} ${orderDir}`;

  query += ' LIMIT 50';

  try {
    const result = await pool.query(query, params);
    res.json({
      products: result.rows,
      meta: { total: result.rows.length, query_id: crypto.randomUUID() }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin endpoint for inventory updates
app.post('/api/v2/admin/inventory', async (req, res) => {
  const session = validateSession(req);
  if (!session) return res.status(401).json({ error: 'unauthorized' });

  const adminHash = crypto.createHash('sha256').update(session).digest('hex');
  const adminCheck = await pool.query(
    'SELECT 1 FROM admin_sessions WHERE session_hash = $1 AND expires_at > NOW()',
    [adminHash]
  );
  if (adminCheck.rows.length === 0) return res.status(403).json({ error: 'forbidden' });

  const { product_id, adjustment } = req.body;
  if (!Number.isInteger(product_id) || !Number.isInteger(adjustment)) {
    return res.status(400).json({ error: 'invalid params' });
  }

  await pool.query(
    'UPDATE products SET stock_count = stock_count + $1 WHERE id = $2',
    [adjustment, product_id]
  );
  res.json({ success: true });
});

app.listen(process.env.PORT || 3000);
